import{_ as w,a0 as l,w as a,s as d,ao as s,I as e,x as n,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"一個八年的 Linux 老用户使用 Windows 10 的體驗 | LCTT x X-CMD","titleTemplate":false,"description":"一個八年的 Linux 老用户使用 Windows 10 的體驗 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一個八年的 Linux 老用户使用 Windows 10 的體驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一個八年的 Linux 老用户使用 Windows 10 的體驗 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20150818 A Linux User Using Windows 10 After More than 8 Years--See Comparison","title":"一個八年的 Linux 老用户使用 Windows 10 的體驗","tag":"201602","desc":""},"relativePath":"201602/20150818 A Linux User Using Windows 10 After More than 8 Years--See Comparison.md","filePath":"[post].md"}'),m={name:"201602/20150818 A Linux User Using Windows 10 After More than 8 Years--See Comparison.md"};function r(c,t,u,g,W,h){const p=l("Link");return a(),d("div",null,[t[15]||(t[15]=s('<h1 id="一個八年的-linux-老用户使用-windows-10-的體驗" tabindex="-1">一個八年的 Linux 老用户使用 Windows 10 的體驗 <a class="header-anchor" href="#一個八年的-linux-老用户使用-windows-10-的體驗" aria-label="Permalink to “一個八年的 Linux 老用户使用 Windows 10 的體驗”">​</a></h1><p>Windows 10 是2015年7月29日上市的最新一代 Windows NT 系列系統，它是 Windows 8.1 的繼任者。Windows 10 支持 Intel 32位平台，AMD64 以及 ARM v7 處理器。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-10-vs-Linux.jpg" alt="Windows 10 and Linux Comparison"></p><p><em>對比：Windows 10與Linux</em></p><p>作為一個連續使用 linux 超過8年的用户，我想要去體驗一下 Windows 10 ，因為有很多關於它的消息。這篇文章是我觀察力的一個重大突破。我將從一個 linux 用户的角度去看待一切，所以這篇文章可能會有些偏向於 linux。儘管如此，本文也絕對不會有任何虛假信息。</p><p>1、用谷歌搜索“download Windows 10”並且點擊第一個鏈接。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Search-Windows-10.jpg" alt="Search Windows 10"></p><p><em>搜索 Windows 10</em></p>',8)),e("p",null,[t[1]||(t[1]=n("你也可以直接打開： [",-1)),i(p,{href:"https://www.microsoft.com/en_us/software-download/Windows10%5B1%5D"},{default:o(()=>[...t[0]||(t[0]=[n("https://www.microsoft.com/en_us/software-download/Windows10[1]",-1)])]),_:1})]),t[16]||(t[16]=s(`<p>2、微軟要求我從 Windows 10， Windows 10 KN， Windows 10 N 和 Windows 10 單語言版中選擇一個版本。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Windows-10-Edition.jpg" alt="Select Windows 10 Edition"></p><p><em>選擇版本</em></p><p>以下是各個版本的簡略信息：</p><ul><li>Windows 10 - 包含微軟提供給我們的所有軟件</li><li>Windows 10N - 此版本不包含媒體播放器</li><li>Windows 10KN - 此版本沒有媒體播放能力</li><li>Windows 10 單語言版 - 僅預裝一種語言</li></ul><p>3、我選擇了第一個選項“Windows 10”並且單擊“確認”。之後我要選擇語言，我選擇了“英語”。</p><p>微軟給我提供了兩個下載鏈接。一個是32位版，另一個是64位版。我單擊了64位版--這與我的電腦架構相同。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Download-Windows-10.jpg" alt="Download Windows 10"></p><p><em>下載 Windows 10</em></p><p>我的帶寬是15M的，下載了整整3個小時。不幸的是微軟沒有提供系統的種子文件，否則整個過程會更加舒暢。鏡像大小為 3.8 GB（LCTT譯者注：就我的10M小水管，我使用迅雷下載用時50分鐘）。</p><p>我找不到更小的鏡像，微軟並沒有為 Windows 提供網絡安裝鏡像。我也沒有辦法在下載完成後去校驗哈希值。（LCTT 譯註：你知道的，這對於 Linux 來説都是常識了）</p><p>我十分驚訝，Windows 在這樣的問題上居然如此漫不經心。為了驗證這個鏡像是否正確下載，我需要把它刻到光盤上或者複製到我的U盤上然後啓動它，一直靜靜的看着它安裝直到安裝完成。</p><p>首先，我用 dd 命令將 win10 的 iso 鏡像刻錄到U盤上。</p><pre><code># dd if=/home/avi/Downloads/Win10_English_x64.iso of=/dev/sdb1 bs=512M; sync
</code></pre><p>這需要一點時間。在此之後我重啓系統並在 UEFI（BIOS）設置中選擇從我的U盤啓動。</p><h4 id="系統要求" tabindex="-1">系統要求 <a class="header-anchor" href="#系統要求" aria-label="Permalink to “系統要求”">​</a></h4><p>升級</p><ul><li>僅支持從 Windows 7 SP1 或者 Windows 8.1 升級</li></ul><p>全新安裝</p><ul><li>處理器: 1GHz 以上</li><li>內存: 1GB以上(32位)，2GB以上(64位)</li><li>硬盤: 16GB以上(32位)，20GB以上(64位)</li><li>顯卡: 支持DirectX 9或更新 + WDDM 1.0 驅動</li></ul><p>###Windows 10 安裝過程###</p><p>1、Windows 10啓動成功了。他們又換了logo，但是仍然沒有信息提示我它正在做什麼。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-10-Logo.jpg" alt="Windows 10 Logo"></p><p><em>Windows 10 Logo</em></p><p>2、選擇安裝語言，時區，鍵盤，輸入法，點擊下一步。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Language-and-Time.jpg" alt="Select Language and Time"></p><p><em>選擇語言和時區</em></p><p>3、點擊“現在安裝”。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Windows-10.jpg" alt="Install Windows 10"></p><p><em>安裝Ｗindows 10</em></p><p>4、下一步是輸入密鑰，我點擊了“跳過”。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-10-Product-Key.jpg" alt="Windows 10 Product Key"></p><p><em>Windows 10 產品密鑰</em></p><p>5、從列表中選擇一個系統版本。我選擇了 Windows 10專業版。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Install-Operating-System.jpg" alt="Select Install Operating System"></p><p><em>選擇系統版本</em></p><p>6、到了協議部分，選中&quot;我接受&quot;然後點擊下一步。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Accept-License.jpg" alt="Accept License"></p><p><em>同意協議</em></p><p>7、下一步是選擇（從 Windows 的老版本）升級到 Windows 10 或者安裝 Ｗindows。我搞不懂為什麼微軟要讓我自己選擇：“安裝Ｗindows”被微軟建議為“高級”選項。但是我還是選擇了“安裝Windows”。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Installation-Type.jpg" alt="Select Installation Type"></p><p><em>選擇安裝類型</em></p><p>8、選擇驅動器，點擊“下一步”。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Install-Drive.jpg" alt="Select Install Drive"></p><p><em>選擇安裝盤</em></p><p>9、安裝程序開始複製文件，準備文件，安裝更新，之後進行收尾。如果安裝程序能在安裝時輸出一堆字符來表示它在做什麼就更好了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Installing-Windows.jpg" alt="Installing Windows"></p><p><em>安裝 Windows</em></p><p>10、在此之後 Windows 重啓了。它們説要繼續的話，我們需要重啓。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-Installation-Process.jpg" alt="Windows Installation Process"></p><p><em>安裝進程</em></p><p>11、我看到了一個寫着“正在準備 Windows”的界面。它停了整整五分多鐘！仍然沒有説明它正在做什麼。沒有輸出。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-Getting-Ready.jpg" alt="Windows Getting Ready"></p><p><em>正在準備 Windows</em></p><p>12、又到了輸入產品密鑰的時間。我點擊了“以後再説”，並使用快速設置。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Enter-Product-Key.jpg" alt="Enter Product Key"></p><p><em>輸入產品密鑰</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Express-Settings.jpg" alt="Select Express Settings"></p><p><em>使用快速設置</em></p><p>13、又出現了三個界面，作為 Linux 用户我認為此處應有信息來告訴我安裝程序在做什麼，但是我想多了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Loading-Windows.jpg" alt="Loading Windows"></p><p><em>載入 Windows</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Getting-Updates.jpg" alt="Getting Updates"></p><p><em>獲取更新</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Still-Loading-Windows.jpg" alt="Still Loading Windows"></p><p><em>還是載入 Ｗindows</em></p><p>14、安裝程序想要知道誰擁有這台機器，“我的組織”或者我自己。選擇我自己並繼續。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Select-Organization.jpg" alt="Select Organization"></p><p><em>選擇組織</em></p><p>15、在單擊繼續之前，安裝程序提示我加入“Aruze Ad”或者“加入域”。我選擇了後者。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Connect-Windows.jpg" alt="Connect Windows"></p><p><em>連接網絡</em></p><p>16、安裝程序讓我新建一個賬户。所以我輸入了“user_name”就點擊了下一步，我覺得我會收到一個要求我必須輸入密碼的信息。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Create-Account.jpg" alt="Create Account"></p><p><em>新建賬户</em></p><p>17、讓我驚訝的是 Windows 甚至都沒有顯示一個警告或提示信息，告訴我必須創建密碼。真粗心。不管怎樣，現在我可以體驗系統了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-10-Desktop.jpg" alt="Windows 10 Desktop"></p><p><em>Windows 10的桌面環境</em></p><h4 id="linux-用户-我-直到現在的體驗" tabindex="-1">Linux 用户(我)直到現在的體驗 <a class="header-anchor" href="#linux-用户-我-直到現在的體驗" aria-label="Permalink to “Linux 用户(我)直到現在的體驗”">​</a></h4><ul><li>沒有網絡安裝鏡像</li><li>鏡像文件太臃腫了</li><li>沒有驗證 iso 是否為正確的方法（官方沒有提供哈希值）</li><li>啓動與安裝方式仍然與 XP，Win 7，Win 8 相同（可能吧...）</li><li>和以前一樣，安裝程序沒有輸出它正在幹什麼 - 正在複製什麼和正在安裝什麼軟件包</li><li>安裝程序比 Linux 發行版的更加傻瓜和簡單</li></ul><p>####測試 Windows 10####</p><p>18、默認桌面很乾淨，上面只有一個回收站圖標。我們可以直接從桌面搜索網絡。底部的快捷方式分別是任務預覽、網絡、微軟應用商店。和以前的版本一樣，消息欄在右下角。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Deskop-Shortcut-icons.jpg" alt=" "></p><p><em>桌面圖標</em></p><p>19、IE 瀏覽器被換成了 Edge 瀏覽器。微軟把他們的老IE換成了 Edge （斯巴達計劃）</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Edge-browser.jpg" alt="Microsoft Edge Browser"></p><p><em>Edge 瀏覽器</em></p><p>測試起來，這個瀏覽器至少比 IE 要快。他們有相同的用户界面。它的主頁包含新聞更新。它還有一個搜索標題欄是“下一步怎麼走”。由於瀏覽器的全面性能提升，它的加載速度非常快。Edge 的內存佔用看起來正常。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-Performance.jpg" alt="Windows Performance"></p><p><em>性能</em></p><p>Edge 也有小娜加成（智能個人助理）、支持 Chrome 擴展、支持筆記（在瀏覽網頁時記筆記）、分享（在選項卡上右擊而不必打開其他選項卡）</p><h4 id="linux-用户-我-此時體驗" tabindex="-1">Linux 用户(我)此時體驗 <a class="header-anchor" href="#linux-用户-我-此時體驗" aria-label="Permalink to “Linux 用户(我)此時體驗”">​</a></h4><p>20、微軟確實提升了網頁瀏覽體驗。我絕對穩定性和質量還好。現在它並不落後。</p><p>21、對我來説，Edge 的內存佔用不算太大。但是有很多用户抱怨它的內存佔用太多。</p><p>22、很難説目前 Edge 已經準備好了與火狐或 Chrome競爭。讓我們靜觀其變。</p><h4 id="更多的視覺體驗" tabindex="-1">更多的視覺體驗 <a class="header-anchor" href="#更多的視覺體驗" aria-label="Permalink to “更多的視覺體驗”">​</a></h4><p>23、重新設計的開始菜單 -- 看起來很簡潔高效。Merto 磁貼大部分都會動。預先放置了最通用的應用。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-Look.jpg" alt="Windows Look and Feel"></p><p><em>Windows</em></p><p>而在 Linux 的 Gnome 桌面環境下。我僅僅需要按下 Win 鍵並輸入應用名就可以搜索應用。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Search-Within-Desktop.jpg" alt="Search Within Desktop"></p><p><em>桌面內進行搜索</em></p><p>24、文件瀏覽器 -- 設計的很簡潔。左邊是進入文件夾的快捷方式。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-File-Explorer.jpg" alt="Windows File Explorer"></p><p><em>Windows 文件管理器</em></p><p>我們的 Gnome 下的文件管理也同樣的簡潔高效。從圖標上移走了不需要的圖形圖像是個加分點。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/File-Browser.jpg" alt="File Browser on Gnome"></p><p><em>Gnome 的文件管理</em></p><p>25、設置 -- 儘管 Windows 10的設置有點精煉，但是我們還是可以把它與 linux 的設置進行對比。</p><p><strong>Windows 的設置</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-10-Settings.jpg" alt="Windows 10 Settings"></p><p><em>Windows 10 設置</em></p><p><strong>Linux Gnome 上的設置</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Gnome-Settings.jpg" alt="Gnome Settings"></p><p><em>Gnome 的設置</em></p><p>26、應用列表 -- 目前，Linux上的應用列表要好於之前的版本（據我所記，那時我還是一個普通的 Windows 用户），但是 Windows 10 的還比 Gnome 3 的差一點。</p><p><strong>Windows 的應用列表</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Application-List-on-Windows-10.jpg" alt="Application List on Windows 10"></p><p><em>Windows 10 的應用列表</em></p><p><strong>Gnome3 的應用列表</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Gnome-Application-List-on-Linux.jpg" alt="Gnome Application List on Linux"></p><p><em>Gnome3 的應用列表</em></p><p>27、虛擬桌面 -- Windows 10 上的虛擬桌面是近來被提及最多的特性之一。</p><p>這是 Windows 10 上的虛擬桌面。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-Virtual-Desktop.jpg" alt="Windows Virtual Desktop"></p><p><em>Windows 的虛擬桌面</em></p><p>這是我們 Linux 用户使用了超過20年的虛擬桌面。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Virtual-Desktop-on-Linux.jpg" alt="Virtual Desktop on Linux"></p><p><em>Linux 的虛擬桌面</em></p><h4 id="windows-10-的其他新特性" tabindex="-1">Windows 10 的其他新特性 <a class="header-anchor" href="#windows-10-的其他新特性" aria-label="Permalink to “Windows 10 的其他新特性”">​</a></h4><p>28、Windows 10 自帶 wifi 感知。它會把你的 wifi 密碼分享給他人。任何在你 wifi 範圍內並且曾經通過 Skype， Outlook， Hotmail 或 Facebook與你聯繫的人都能夠獲得你的網絡接入權。這個特性的本意是讓用户可以省時省力的連接網絡。</p><p>在微軟對於 Tecmint 的問題的回答中，他們説道 -- 用户需要在每次到一個新的網絡環境時自己去同意打開 wifi 感知。如果我們考慮到網絡安全這將是很不安全的一件事。微軟的説法並沒有説服我。</p><p>29、從 Windows 7 和 Windows 8.1 升級可以省下買新版的花費。（家庭版 $119 專業版$199）</p><p>30、微軟發佈了第一個累積更新，這個更新在一小部分設備上會讓系統一直重啓。Windows可能不知道這個問題或者不知道它發生的原因。</p><p>31、微軟內建的“禁用/隱藏我不想要的更新”的功能在我這不起作用。這意味着一旦更新開始推送，你沒有方法去禁用/隱藏他們。對不住啦，Windows 用户。</p><h4 id="windows-10-包含的來源於-linux-的功能" tabindex="-1">Windows 10 包含的來源於 Linux 的功能 <a class="header-anchor" href="#windows-10-包含的來源於-linux-的功能" aria-label="Permalink to “Windows 10 包含的來源於 Linux 的功能”">​</a></h4><p>Windows 10 有很多直接取自 Linux 的功能。如果 Linux 不以 GPL 發佈的話，也許以下這些功能永遠不會出現在 Windows上。</p><p>32、命令列的包管理器 -- 是的，你沒有聽錯！Windows 10內建了一個包管理器。它只在 Power Shell 下工作。OneGet 是Windows 的官方包管理器。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Windows-10-Package-Manager.jpg" alt="Windows 10 Package Manager"></p><p><em>Windows 10的包管理器</em></p><ul><li>無邊窗口</li><li>扁平化圖標</li><li>虛擬桌面</li><li>離線/在線搜索一體化</li><li>手機/桌面系統融合</li></ul><h3 id="總體印象" tabindex="-1">總體印象### <a class="header-anchor" href="#總體印象" aria-label="Permalink to “總體印象###”">​</a></h3><ul><li>響應速度提升</li><li>動畫很好看</li><li>資源佔用少</li><li>電池續航提升</li><li>Edge 瀏覽器很穩定</li><li>支持樹莓派 2</li><li>Windows 10 好的原因是 Windows 8/8.1 沒有達到公眾預期並且壞的可以</li><li>舊瓶裝新酒：Windows 10基本上就是以前的那一套換上新的圖標</li></ul><p>測試後我對 Windows 10 的評價是：Windows 10 在視覺和感覺上做了一些更新（就如同 Windows 經常做的那樣）。我要為斯巴達計劃、虛擬桌面、命令列包管理器、整合在線/離線搜索的搜索欄點贊。這確實是一個更新後的產品 ，但是認為 Windows 10 將是 Linux 的最後一個棺材釘的人錯了。</p><p>Linux 走在 Windows 前面。它們的做事方法並不相同。在以後的一段時間裏 Windows 不會站到 Linux這一旁。也沒有什麼讓 Linux 用户值得去使用 Windows 10。</p><p>這就是我要説的。希望你喜歡本文。如果你們喜歡本篇文章我會再寫一些你們喜歡讀的有趣的文章。在下方留下你的有價值的評論。</p><hr>`,147)),e("p",null,[t[3]||(t[3]=n("via: ",-1)),i(p,{href:"http://www.tecmint.com/a-linux-user-using-Windows-10-after-more-than-8-years-see-comparison/"},{default:o(()=>[...t[2]||(t[2]=[n("http://www.tecmint.com/a-linux-user-using-Windows-10-after-more-than-8-years-see-comparison/",-1)])]),_:1})]),e("p",null,[t[7]||(t[7]=n("作者：",-1)),i(p,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...t[4]||(t[4]=[n("Avishek Kumar",-1)])]),_:1}),t[8]||(t[8]=n(" 譯者：",-1)),i(p,{href:"https://github.com/name1e5s"},{default:o(()=>[...t[5]||(t[5]=[n("name1e5s",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=n("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創翻譯，",-1)),i(p,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const S=w(m,[["render",r]]);export{f as __pageData,S as default};
